func (this *Bittrade) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchDeposits
	//
	//     {
	//         "id": 8211029,
	//         "type": "deposit",
	//         "currency": "eth",
	//         "chain": "eth",
	//         'tx-hash': "bd315....",
	//         "amount": 0.81162421,
	//         "address": "4b8b....",
	//         'address-tag": '",
	//         "fee": 0,
	//         "state": "safe",
	//         "created-at": 1542180380965,
	//         "updated-at": 1542180788077
	//     }
	//
	// fetchWithdrawals
	//
	//     {
	//         "id": 6908275,
	//         "type": "withdraw",
	//         "currency": "btc",
	//         "chain": "btc",
	//         'tx-hash': "c1a1a....",
	//         "amount": 0.80257005,
	//         "address": "1QR....",
	//         'address-tag": '",
	//         "fee": 0.0005,
	//         "state": "confirmed",
	//         "created-at": 1552107295685,
	//         "updated-at": 1552108032859
	//     }
	//
	// withdraw
	//
	//     {
	//         "status": "ok",
	//         "data": "99562054"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var timestamp any = this.SafeInteger(transaction, "created-at")
	var code any = this.SafeCurrencyCode(this.SafeString(transaction, "currency"))
	var typeVar any = this.SafeString(transaction, "type")
	if IsTrue(IsEqual(typeVar, "withdraw")) {
		typeVar = "withdrawal"
	}
	var feeCost any = this.SafeString(transaction, "fee")
	if IsTrue(!IsEqual(feeCost, nil)) {
		feeCost = Precise.StringAbs(feeCost)
	}
	return map[string]any{
		"info":        transaction,
		"id":          this.SafeString2(transaction, "id", "data"),
		"txid":        this.SafeString(transaction, "tx-hash"),
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     this.SafeStringUpper(transaction, "chain"),
		"address":     this.SafeString(transaction, "address"),
		"addressTo":   nil,
		"addressFrom": nil,
		"tag":         this.SafeString(transaction, "address-tag"),
		"tagTo":       nil,
		"tagFrom":     nil,
		"type":        typeVar,
		"amount":      this.SafeNumber(transaction, "amount"),
		"currency":    code,
		"status":      this.ParseTransactionStatus(this.SafeString(transaction, "state")),
		"updated":     this.SafeInteger(transaction, "updated-at"),
		"comment":     nil,
		"internal":    nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(feeCost),
			"rate":     nil,
		},
	}
}
func (this *Bittrade) ParseTransactionStatus(status any) any {
	var statuses map[string]any = map[string]any{
		"unknown":         "failed",
		"confirming":      "pending",
		"confirmed":       "ok",
		"safe":            "ok",
		"orphan":          "failed",
		"submitted":       "pending",
		"canceled":        "canceled",
		"reexamine":       "pending",
		"reject":          "failed",
		"pass":            "pending",
		"wallet-reject":   "failed",
		"confirm-error":   "failed",
		"repealed":        "failed",
		"wallet-transfer": "pending",
		"pre-transfer":    "pending",
	}
	return this.SafeString(statuses, status, status)
}

/**
 * @method
 * @name bittrade#withdraw
 * @description make a withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Bittrade) WithdrawAsync(code any, amount any, address any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Bittrade) withdrawBody(ch chan any, code any, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	tag := GetArg(optionalArgs, 0, nil)
	_ = tag
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	tagparamsVariable := this.HandleWithdrawTagAndParams(tag, params)
	tag = GetValue(tagparamsVariable, 0)
	params = GetValue(tagparamsVariable, 1)
	if IsTrue(IsEqual(this.Markets, nil)) {

		retRes206712 := (<-this.LoadMarketsAsync())
		PanicOnError(retRes206712)
	}
	this.CheckAddress(address)
	var currency any = this.Currency(code)
	var request map[string]any = map[string]any{
		"address":  address,
		"amount":   amount,
		"currency": ToLower(GetValue(currency, "id")),
	}
	if IsTrue(!IsEqual(tag, nil)) {
		AddElementToObject(request, "addr-tag", tag) // only for XRP?
	}
	var networks any = this.SafeValue(this.Options, "networks", map[string]any{})
	var network any = this.SafeStringUpper(params, "network")  // this line allows the user to specify either ERC20 or ETH
	network = this.SafeStringLower(networks, network, network) // handle ETH>ERC20 alias
	if IsTrue(!IsEqual(network, nil)) {
		// possible chains - usdterc20, trc20usdt, hrc20usdt, usdt, algousdt
		if IsTrue(IsEqual(network, "erc20")) {
			AddElementToObject(request, "chain", Add(GetValue(currency, "id"), network))
		} else {
			AddElementToObject(request, "chain", Add(network, GetValue(currency, "id")))
		}
		params = this.Omit(params, "network")
	}

	response := (<-this.PrivatePostDwWithdrawApiCreate(this.Extend(request, params)))
	PanicOnError(response)

	//
	//     {
	//         "status": "ok",
	//         "data": "99562054"
	//     }
	//
	ch <- this.ParseTransaction(response, currency)
	return nil
}
func (this *Bittrade) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var url any = "/"
	if IsTrue(IsEqual(api, "market")) {
		url = Add(url, api)
	} else if IsTrue(IsTrue((IsEqual(api, "public"))) || IsTrue((IsEqual(api, "private")))) {
		url = Add(url, this.Version)
	} else if IsTrue(IsTrue((IsEqual(api, "v2Public"))) || IsTrue((IsEqual(api, "v2Private")))) {
		url = Add(url, "v2")
	}
	url = Add(url, Add("/", this.ImplodeParams(path, params)))
	var query any = this.Omit(params, this.ExtractParams(path))
	if IsTrue(IsTrue(IsEqual(api, "private")) || IsTrue(IsEqual(api, "v2Private"))) {
		this.CheckRequiredCredentials()
		var timestamp string = this.Ymdhms(this.Milliseconds(), "T")
		var request map[string]any = map[string]any{
			"SignatureMethod":  "HmacSHA256",
			"SignatureVersion": "2",
			"AccessKeyId":      this.ApiKey,
			"Timestamp":        timestamp,
		}
		if IsTrue(!IsEqual(method, "POST")) {
			request = this.Extend(request, query)
		}
		var requestSorted map[string]any = this.Keysort(request)
		var auth any = this.Urlencode(requestSorted)
		// unfortunately, PHP demands double quotes for the escaped newline symbol
		var content []any = []any{method, this.Hostname, url, auth}
		// eslint-disable-next-line quotes
		var payload string = Join(content, "\n")
		var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha256, "base64")
		auth = Add(auth, Add("&", this.Urlencode(map[string]any{
			"Signature": signature,
		})))
		url = Add(url, Add("?", auth))
		if IsTrue(IsEqual(method, "POST")) {
			body = this.Json(query)
			headers = map[string]any{
				"Content-Type": "application/json",
			}
		} else {
			headers = map[string]any{
				"Content-Type": "application/x-www-form-urlencoded",
			}
		}
	} else {
		if IsTrue(IsGreaterThan(GetArrayLength(ObjectKeys(params)), 0)) {
			url = Add(url, Add("?", this.Urlencode(params)))
		}
	}
	url = Add(this.ImplodeParams(GetValue(GetValue(this.Urls, "api"), api), map[string]any{
		"hostname": this.Hostname,
	}), url)
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *Bittrade) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsTrue(IsEqual(response, nil)) {
		return nil // fallback to default error handler
	}
	if IsTrue(InOp(response, "status")) {
		//
		//     {"status":"error","err-code":"order-limitorder-amount-min-error","err-msg":"limit order amount error, min: `0.001`","data":null}
		//
		var status any = this.SafeString(response, "status")
		if IsTrue(IsEqual(status, "error")) {
			var code any = this.SafeString(response, "err-code")
			var feedback any = Add(Add(this.Id, " "), body)
			this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), body, feedback)
			this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), code, feedback)
			var message any = this.SafeString(response, "err-msg")
			this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), message, feedback)
			panic(ExchangeError(feedback))
		}
	}
	return nil
}

